needle='''def sentiment(title):\n    p=sum(1 for w in POS_WORDS if w in title); n=sum(1 for w in NEG_WORDS if w in title)\n    return p-n\n\ndef scan_market(progress=None, topn=40):\n'''
repl='''def sentiment(title):\n    p=sum(1 for w in POS_WORDS if w in title); n=sum(1 for w in NEG_WORDS if w in title)\n    return p-n\n\ndef market_environment():\n    """네이버 시장지표를 읽어 환율·달러·금리 환경을 별도 점수화한다."""\n    html=http_text(MARKETINDEX_URL)\n    lp=LinkParser(); lp.feed(html)\n    rp=RowParser(); rp.feed(html)\n    texts=[]\n    wanted=("미국 USD","일본 JPY","유럽연합 EUR","중국 CNY","달러/일본 엔","유로/달러","영국 파운드/달러","달러인덱스","달러 인덱스","WTI","국제 금","국내 금")\n    for href,t in lp.links:\n        t=re.sub(r"\\s+"," ",t).strip()\n        if t and any(k in t for k in wanted) and t not in texts:texts.append(t)\n    rate_rows=[]\n    for cells,links in rp.rows:\n        row=" | ".join(x for x in cells if x)\n        if any(k in row for k in ("CD금리","콜 금리","국고채","회사채","COFIX")):\n            rate_rows.append(row)\n    score=50; reasons=[]\n    def direction_adjust(keys, up_delta, down_delta, label):\n        nonlocal score\n        hit=next((x for x in texts if any(k in x for k in keys)),"")\n        if hit:\n            if "상승" in hit:score+=up_delta; reasons.append(f"{label} 상승 {up_delta:+d}")\n            elif "하락" in hit:score+=down_delta; reasons.append(f"{label} 하락 {down_delta:+d}")\n    direction_adjust(("미국 USD",),-7,+7,"원/달러")\n    direction_adjust(("달러인덱스","달러 인덱스"),-5,+5,"달러인덱스")\n    kr3=next((x for x in rate_rows if "국고채" in x and "3년" in x),"")\n    if kr3:\n        if "상승" in kr3:score-=4;reasons.append("국고채3년 상승 -4")\n        elif "하락" in kr3:score+=4;reasons.append("국고채3년 하락 +4")\n    wti=next((x for x in texts if x.startswith("WTI") or " WTI" in x),"")\n    if wti:\n        if "상승" in wti:score-=1;reasons.append("WTI 상승 -1")\n        elif "하락" in wti:score+=1;reasons.append("WTI 하락 +1")\n    score=max(0,min(100,score))\n    verdict="매우 우호" if score>=65 else "우호" if score>=56 else "중립" if score>=45 else "부담" if score>=35 else "위험회피"\n    return {"score":score,"verdict":verdict,"items":texts[:14],"rates":rate_rows[:10],"reasons":reasons}\n\ndef scan_market(progress=None, topn=40):\n'''
if needle not in s: raise SystemExit('patch anchor 1 missing')
