market_method='''    def _market_tab(self):\n        f=self.tabs["market"];bar=tk.Frame(f,bg="#0f172a");bar.pack(fill="x",padx=14,pady=12)\n        self.btn(bar,"🌍 시장환경 새로고침",self.refresh_market_env,True).pack(side="left")\n        tk.Label(bar,text="원/달러 · 달러인덱스 · WTI · 국내금리 → 종목점수와 분리된 시장환경 보조점수",bg="#0f172a",fg="#60a5fa",font=("Malgun Gothic",10)).pack(side="left",padx=14)\n        pan=tk.PanedWindow(f,orient="horizontal",bg="#0f172a",sashwidth=5);pan.pack(fill="both",expand=True,padx=14,pady=(0,14))\n        left=tk.Frame(pan,bg="#0f172a");right=tk.Frame(pan,bg="#0f172a");pan.add(left,minsize=500);pan.add(right,minsize=450)\n        self.market_score=tk.Label(left,text="시장환경 --",bg="#111827",fg="#fbbf24",font=("Malgun Gothic",25,"bold"),pady=18);self.market_score.pack(fill="x")\n        self.market_tree=self.tree(left,["시장지표","현재 상태"],[180,520]);self.market_tree.pack(fill="both",expand=True,pady=(10,0))\n        self.market_text=tk.Text(right,bg="#0b1220",fg="#e5e7eb",font=("Malgun Gothic",11),wrap="word",relief="flat");self.market_text.pack(fill="both",expand=True)\n        self.market_env_cache=None\n    def refresh_market_env(self):\n        self.market_score.config(text="시장환경 분석 중...")\n        self.market_tree.delete(*self.market_tree.get_children());self.market_text.delete("1.0","end")\n        def work():\n            try:env=market_environment();self.market_env_cache=env;self.after(0,lambda:self.fill_market_env(env))\n            except Exception as e:self.after(0,lambda:messagebox.showerror("시장환경",str(e)))\n        threading.Thread(target=work,daemon=True).start()\n    def fill_market_env(self,env):\n        self.market_score.config(text=f"시장환경 {env['score']:.0f}/100 · {env['verdict']}")\n        for x in env["items"]:self.market_tree.insert("","end",values=("환율/원자재",x))\n        for x in env["rates"]:self.market_tree.insert("","end",values=("국내금리",x))\n        reasons="\\n".join("• "+x for x in env["reasons"]) or "• 뚜렷한 가감점 신호 없음"\n        txt=f"[마샬 시장환경 판독]\\n\\n점수 {env['score']:.0f}/100 · {env['verdict']}\\n\\n[점수 근거]\\n{reasons}\\n\\n이 점수는 개별 종목의 차트·수급·테마 강도와 별도로 계산하며, 초특급 TOP20의 최종 진입매력도에 7%만 반영합니다. 환율·금리만으로 종목을 매수/매도하지 않습니다."\n        self.market_text.insert("end",txt);self.refresh_diag()\n\n'''
